import { Paise, paiseToDecimal } from '@/domain/money';
import { ParsedUpi } from './parse';

export interface BuildPayUriInput {
  vpa: string;
  payeeName: string;
  /** Amount to pre-fill. Omit to let the PSP app ask for it. */
  amountPaise?: Paise;
  note?: string;
  /** Unique reference (tr). Generated by the caller so it can be matched back to a payment attempt. */
  txnRef?: string;
  /** The scanned QR this payment originates from, if any. */
  source?: ParsedUpi;
}

const enc = encodeURIComponent;

/**
 * Build the `upi://pay` URI to hand to a PSP app.
 *
 * - Signed QR (`sign`): replayed byte-for-byte. Altering any parameter invalidates the signature.
 * - Merchant QR without a signature: replayed, and `am`/`cu` are appended when the QR has no fixed amount.
 * - Everything else (personal VPAs, including "pseudo-merchant" QRs that carry mc/mode/purpose): a clean
 *   P2P URI with only pa, pn, am, cu, tn, tr, because PSPs reject merchant fields on personal VPAs.
 */
export function buildPayUri(input: BuildPayUriInput): string {
  const { source } = input;

  if (source?.isSigned) {
    return `upi://pay?${source.rawQuery}`;
  }

  if (source?.isMerchant) {
    let query = source.rawQuery;
    if (source.amountPaise === undefined && input.amountPaise !== undefined) {
      query += `&am=${paiseToDecimal(input.amountPaise)}`;
    }
    if (!source.params.cu) query += '&cu=INR';
    return `upi://pay?${query}`;
  }

  const parts = [`pa=${enc(input.vpa)}`, `pn=${enc(input.payeeName || 'Payee')}`];
  if (input.amountPaise !== undefined) parts.push(`am=${paiseToDecimal(input.amountPaise)}`);
  parts.push('cu=INR');
  const note = input.note?.trim();
  if (note) parts.push(`tn=${enc(note.slice(0, 80))}`);
  if (input.txnRef) parts.push(`tr=${enc(input.txnRef)}`);
  return `upi://pay?${parts.join('&')}`;
}

/**
 * Same payment without a pre-filled amount, for PSP apps that decline P2P intents carrying `am`.
 * Signed QRs are never altered.
 */
export function buildPayUriWithoutAmount(input: BuildPayUriInput): string {
  if (input.source?.isSigned) return buildPayUri(input);
  return buildPayUri({ ...input, amountPaise: undefined });
}

/** UPI transaction references: 1–35 alphanumerics. */
export function generateTxnRef(now: number, random: () => number = Math.random): string {
  const time = now.toString(36).toUpperCase();
  const rand = Math.floor(random() * 36 ** 6)
    .toString(36)
    .toUpperCase()
    .padStart(6, '0');
  return `SS${time}${rand}`.slice(0, 35);
}
